@@ -40,6 +46,13 @@ OsdManager::OsdManager(QObject *parent)

 void OsdManager::hideOsd()
 {
+    if (m_revertConfig) {
+        // A change still waits for confirmation, quitting now would keep it
+        for (auto osd : std::as_const(m_osds)) {
+            osd->hideOsd();
+        }
+        return;
+    }
     // Let QML engine finish execution of signal handlers, if any.
     QTimer::singleShot(0, this, &OsdManager::quit);
 }
@@ -48,6 +61,7 @@ void OsdManager::quit()
 {
     qDeleteAll(m_osds);
     m_osds.clear();
+    m_confirmation.reset();
     qApp->quit();
 }

@@ -102,19 +116,108 @@ void OsdManager::showActionSelector()
             osd = new KScreen::Osd(osdOutput, this);
             m_osds.insert(osdOutput->name(), osd);
             connect(osd, &Osd::osdActionSelected, this, [this, cfg = op->config()](OsdAction::Action action) {
-                auto job = OsdAction::applyAction(cfg, action);
-                if (!job) {
-                    hideOsd();
-                    return;
-                }
-                connect(job, &KScreen::SetConfigOperation::finished, this, &OsdManager::hideOsd);
+                applyActionToConfig(cfg, action);
             });
         }

         osd->showActionSelector();
-        m_cleanupTimer->start();
+        if (!m_revertConfig) {
+            m_cleanupTimer->start();
+        }
     });
 }
+
+void OsdManager::applyAction(int action)
+{
+    connect(new KScreen::GetConfigOperation(), &KScreen::GetConfigOperation::finished, this, [this, action](const KScreen::ConfigOperation *op) {
+        if (op->hasError()) {
+            qWarning() << op->errorString();
+            hideOsd();
+            return;
+        }
+        applyActionToConfig(op->config(), static_cast<OsdAction::Action>(action));
+    });
+}
+
+void OsdManager::applyActionToConfig(const KScreen::ConfigPtr &config, OsdAction::Action action)
+{
+    auto job = OsdAction::applyAction(config, action);
+    if (!job) {
+        hideOsd();
+        return;
+    }
+    // When a change is made before the previous one was confirmed, still offer to go back to the last confirmed one
+    if (!m_revertConfig) {
+        m_revertConfig = config;
+    }
+    m_cleanupTimer->stop();
+    connect(job, &KScreen::SetConfigOperation::finished, this, [this](KScreen::ConfigOperation *op) {
+        if (op->hasError()) {
+            qWarning() << op->errorString();
+            m_revertConfig.reset();
+            hideOsd();
+            return;
+        }
+        showConfirmation();
+    });
+}
+
+void OsdManager::showConfirmation()
+{
+    if (!m_confirmation) {
+        m_confirmationEngine = std::make_unique<QQmlEngine>();
+        Plasma::setupPlasmaStyle(m_confirmationEngine.get());
+        m_confirmation = std::make_unique<QQuickView>(m_confirmationEngine.get(), nullptr);
+        m_confirmation->loadFromModule("org.kde.kscreen.osd", "OsdConfirmation");
+        m_confirmation->setColor(Qt::transparent);
+        m_confirmation->setFlag(Qt::FramelessWindowHint);
+
+        if (m_confirmation->status() != QQuickView::Ready) {
+            qWarning() << "Failed to load OSD confirmation QML file";
+            m_confirmation.reset();
+            keepConfig();
+            return;
+        }
+
+        auto rootObject = m_confirmation->rootObject();
+        connect(rootObject, SIGNAL(keep()), this, SLOT(keepConfig()));
+        connect(rootObject, SIGNAL(revert()), this, SLOT(revertConfig()));
+
+        // The outputs just changed, let the compositor pick one that is in use
+        auto layerWindow = LayerShellQt::Window::get(m_confirmation.get());
+        layerWindow->setScope(QStringLiteral("on-screen-display"));
+        layerWindow->setLayer(LayerShellQt::Window::LayerOverlay);
+        layerWindow->setAnchors({});
+        layerWindow->setKeyboardInteractivity(LayerShellQt::Window::KeyboardInteractivityOnDemand);
+        layerWindow->setWantsToBeOnActiveScreen(true);
+    }
+
+    QMetaObject::invokeMethod(m_confirmation->rootObject(), "start");
+    m_confirmation->setVisible(true);
+}
+
+void OsdManager::keepConfig()
+{
+    m_revertConfig.reset();
+    if (m_confirmation) {
+        m_confirmation->setVisible(false);
+    }
+    hideOsd();
+}
+
+void OsdManager::revertConfig()
+{
+    if (m_confirmation) {
+        m_confirmation->setVisible(false);
+    }
+    if (!m_revertConfig) {
+        hideOsd();
+        return;
+    }
+    auto job = new KScreen::SetConfigOperation(m_revertConfig);
+    m_revertConfig.reset();
+    connect(job, &KScreen::SetConfigOperation::finished, this, &OsdManager::hideOsd);
+}
 }

