@@ -0,0 +1,126 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+pragma ComponentBehavior: Bound
+
+import QtQuick
+import QtQuick.Controls
+import QtQuick.Layouts
+
+import org.kde.ksvg as KSvg
+import org.kde.kirigami as Kirigami
+import org.kde.plasma.components as PlasmaComponents
+
+Control {
+    id: root
+
+    property int revertCountdown: 15
+
+    signal keep()
+    signal revert()
+
+    function start() {
+        revertCountdown = 15;
+        revertTimer.restart();
+        revertButton.forceActiveFocus();
+    }
+
+    leftPadding: shadow.margins.left + backgroundItem.margins.left + Kirigami.Units.largeSpacing
+    rightPadding: shadow.margins.right + backgroundItem.margins.right + Kirigami.Units.largeSpacing
+    topPadding: shadow.margins.top + backgroundItem.margins.top + Kirigami.Units.largeSpacing
+    bottomPadding: shadow.margins.bottom + backgroundItem.margins.bottom + Kirigami.Units.largeSpacing
+
+    Timer {
+        id: revertTimer
+        interval: 1000
+        repeat: true
+        onTriggered: {
+            root.revertCountdown -= 1;
+            if (root.revertCountdown < 1) {
+                stop();
+                root.revert();
+            }
+        }
+    }
+
+    contentItem: ColumnLayout {
+        spacing: Kirigami.Units.largeSpacing
+
+        Keys.onPressed: event => {
+            switch (event.key) {
+            case Qt.Key_Return:
+            case Qt.Key_Enter:
+                event.accepted = true;
+                if (keepButton.activeFocus) {
+                    keepButton.clicked();
+                } else {
+                    revertButton.clicked();
+                }
+                break;
+            case Qt.Key_Escape:
+                event.accepted = true;
+                revertButton.clicked();
+                break;
+            }
+        }
+
+        Kirigami.Heading {
+            Layout.fillWidth: true
+            text: i18n("Keep display configuration?")
+            horizontalAlignment: Text.AlignHCenter
+            wrapMode: Text.WordWrap
+        }
+
+        PlasmaComponents.Label {
+            Layout.fillWidth: true
+            text: i18np("Will revert to previous configuration in %1 second.",
+                        "Will revert to previous configuration in %1 seconds.",
+                        root.revertCountdown)
+            horizontalAlignment: Text.AlignHCenter
+            wrapMode: Text.WordWrap
+        }
+
+        RowLayout {
+            Layout.alignment: Qt.AlignHCenter
+            spacing: Kirigami.Units.smallSpacing
+
+            PlasmaComponents.Button {
+                id: keepButton
+                icon.name: "dialog-ok"
+                text: i18n("&Keep")
+                onClicked: {
+                    revertTimer.stop();
+                    root.keep();
+                }
+            }
+
+            PlasmaComponents.Button {
+                id: revertButton
+                icon.name: "edit-undo"
+                text: i18n("&Revert")
+                onClicked: {
+                    revertTimer.stop();
+                    root.revert();
+                }
+            }
+        }
+    }
+
+    background: KSvg.FrameSvgItem {
+        id: shadow
+        imagePath: "dialogs/background"
+        prefix: "shadow"
+
+        KSvg.FrameSvgItem {
+            id: backgroundItem
+            anchors.leftMargin: shadow.margins.left
+            anchors.rightMargin: shadow.margins.right
+            anchors.topMargin: shadow.margins.top
+            anchors.bottomMargin: shadow.margins.bottom
+            anchors.fill: parent
+            imagePath: "solid/dialogs/background"
+        }
+    }
+}
